import Fastify from 'fastify'; import cookie from '@fastify/cookie'; import { Pool } from 'pg'; import { z } from 'zod'; import { createHash, randomUUID, randomInt } from 'node:crypto'; import { hashPassword, verifyPassword, newOpaqueSecret, digest, validatePassword, safeEqual } from '@favlib/auth'; import { classify, normalizeText, type CatalogMedia } from '@favlib/catalog'; import { sameSiteUrl, sourceDispositionFromUrl, sourceIdentityFromUrl, suspiciousPageMetadata } from '@favlib/metadata'; import { position, acceptObservation } from '@favlib/progression'; import { previewDeclarative, validateDeclarative } from '@favlib/sources'; import { EXTENSION_PROTOCOL, MINIMUM_EXTENSION_PROTOCOL, pairingChallengeContract, importBatchContract, registerRequestContract, adminInvitationCreateContract, adminUserPatchContract, extensionPageMetadataContract, extensionPreferencesPatchContract, extensionProposalResultContract, extensionReleaseContract } from '@favlib/contracts'; import { OPERATIONAL_DEFAULTS, operationalSettingSchemas, operationalSettingsPatchSchema, runtimeEnvironment, SECURITY_LIMITS, type OperationalSettingKey, buildVersion } from '@favlib/config'; import { BOOTSTRAP_SCHEMA_VERSION, inspectRuntimeSchema } from './runtime-schema.js';
import { activeProviderSql, libraryFilterKeys, libraryFilterSql, libraryFilterValues, libraryProjectionSql, libraryQuerySchema, retainSelected, type LibraryFilterKey } from './library-query.js';
import { openApiDocument } from '@favlib/contracts/openapi';
import { serializerCompiler,validatorCompiler,type ZodTypeProvider } from 'fastify-type-provider-zod';
const runtime=runtimeEnvironment();
const pool = new Pool({connectionString:runtime.databaseUrl});
if(runtime.nodeEnv!=='test') { const schema=await inspectRuntimeSchema(pool); if(!schema.ok) throw new Error(`Schéma FavLib insuffisant (${BOOTSTRAP_SCHEMA_VERSION}), tables absentes: ${schema.missing.join(', ')}`); }
async function operationalValue<K extends OperationalSettingKey>(key:K):Promise<number>{const result=await pool.query('SELECT value FROM operational_setting WHERE key=$1',[key]);if(!result.rowCount)return OPERATIONAL_DEFAULTS[key];const parsed=operationalSettingSchemas[key].safeParse(result.rows[0].value);return parsed.success?parsed.data:OPERATIONAL_DEFAULTS[key]}
async function rateLimit(bucket:string,subject:string,limit:number,windowMinutes:number){const result=await pool.query(`INSERT INTO security_rate_limit(bucket,subject_hash,attempt_count) VALUES($1,$2,1) ON CONFLICT(bucket,subject_hash) DO UPDATE SET attempt_count=CASE WHEN security_rate_limit.window_started_at<now()-make_interval(mins=>$4) THEN 1 ELSE security_rate_limit.attempt_count+1 END,window_started_at=CASE WHEN security_rate_limit.window_started_at<now()-make_interval(mins=>$4) THEN now() ELSE security_rate_limit.window_started_at END,blocked_until=CASE WHEN security_rate_limit.window_started_at<now()-make_interval(mins=>$4) THEN NULL WHEN security_rate_limit.attempt_count+1>$3 THEN now()+make_interval(secs=>LEAST(3600,power(2,LEAST(10,security_rate_limit.attempt_count+1-$3))::int*60)) ELSE security_rate_limit.blocked_until END,updated_at=now() RETURNING blocked_until`,[bucket,digest(subject),limit,windowMinutes]);return Boolean(result.rows[0]?.blocked_until&&new Date(result.rows[0].blocked_until)>new Date())}
function requireWebOrigin(req:any,reply:any){if(req.headers.origin!==origin)return err(reply,403,'ORIGIN_MISMATCH','Origine Web refusée.');return true}
async function enqueueMetadata(db:{query:(sql:string,values?:unknown[])=>Promise<unknown>},userId:string,mediaId:string,title:string,url:string){const fingerprint=createHash('sha256').update(JSON.stringify({title,url})).digest('hex');await db.query("SELECT graphile_worker.add_job('resolve-favorite',$1,job_key := $2,max_attempts := $3)",[JSON.stringify({userId,mediaId,title,url}),`resolve-favorite:${mediaId}:anilist-v1:${fingerprint}`,OPERATIONAL_DEFAULTS['metadata.maxAttempts']])}
const app=Fastify({logger:{redact:['req.headers.cookie','req.headers.authorization','*.password','*.token','*.invitationToken','*.deviceToken','*.activation_token','*.activationToken']},bodyLimit:SECURITY_LIMITS.providerResponseBytesMax}).withTypeProvider<ZodTypeProvider>();app.setValidatorCompiler(validatorCompiler);app.setSerializerCompiler(serializerCompiler); await app.register(cookie);
const runtimeRouteOperations=new Map<string,Set<string>>();app.addHook('onRoute',route=>{const path=route.url.replace(/:([A-Za-z0-9_]+)/g,'{$1}');const methods=Array.isArray(route.method)?route.method:[route.method];const current=runtimeRouteOperations.get(path)??new Set<string>();for(const method of methods)if(method!=='HEAD')current.add(method.toLowerCase());runtimeRouteOperations.set(path,current)});
function runtimeOpenApi(){const paths:any={...(openApiDocument as any).paths};for(const [path,methods] of runtimeRouteOperations){paths[path]??={};for(const method of methods)paths[path][method]??={responses:{default:{description:'Structured FavLib response'}}}}return {...openApiDocument,paths}}
const origin=runtime.baseUrl;
const pairingUrl=(id:string)=>`${origin}/settings?pairing=${encodeURIComponent(id)}#extension`;
app.addHook('onRequest',async(req,reply)=>{ const id=typeof req.headers['x-request-id']==='string'&&/^[A-Za-z0-9._-]{1,80}$/.test(req.headers['x-request-id'])?req.headers['x-request-id']: `req_${randomUUID()}`; reply.header('X-Request-Id',id); (req as any).requestId=id; });
function err(reply:any,status:number,code:string,message='La requête est invalide.',fields:any[]=[]){return reply.code(status).send({error:{code,message,requestId:(reply as any).request?.requestId??'unknown',fields}})}
async function auth(req:any,reply:any){ if(req.url.startsWith('/api/v1/public/')||req.url.startsWith('/api/v1/calendar/feeds/')&&req.method==='GET'||req.url==='/api/v1/auth/register'||req.url==='/api/v1/auth/password-reset'){req.user={id:null,role:'member'};return;} const raw=req.cookies['__Host-favlib_session']; if(!raw)return err(reply,401,'UNAUTHENTICATED','Authentification requise.'); const r=await pool.query('SELECT u.id,u.email,u.role,s.id session_id,s.csrf_hash FROM user_session s JOIN app_user u ON u.id=s.user_id WHERE s.token_hash=$1 AND u.active AND s.revoked_at IS NULL AND s.expires_at>now() AND s.absolute_expires_at>now()', [digest(raw)]); if(!r.rowCount)return err(reply,401,'UNAUTHENTICATED','Authentification requise.'); req.user=r.rows[0]; }
function csrf(req:any,reply:any){ if(req.url==='/api/v1/auth/register'||req.url==='/api/v1/auth/password-reset'||req.url.startsWith('/api/v1/public/'))return true; if(!['POST','PATCH','DELETE'].includes(req.method))return true; if(req.headers.origin!==origin)return err(reply,403,'ORIGIN_MISMATCH','Origine refusée.'); const token=req.headers['x-csrf-token']; if(typeof token!=='string'||!req.user||!safeEqual(digest(token),req.user.csrf_hash))return err(reply,403,'CSRF_FAILED','Protection CSRF refusée.'); return true; }
app.addHook('preHandler',async(req:any,reply:any)=>{
  const path=req.url.split('?')[0];
  const match=path.match(/^\/api\/v1\/(?:catalog\/media|extension\/favorites)\/([^/]+)\/(?:cover|banner)$/);
  if(!match||!req.user?.id)return;
  const mediaId=decodeURIComponent(match[1]);
  const allowed=await pool.query(`SELECT 1 FROM bookmark_media_link l WHERE l.user_id=$1 AND l.media_id=$2 AND l.status IN ('matched','accepted') AND ${activeProviderSql} LIMIT 1`,[req.user.id,mediaId]);
  if(!allowed.rowCount)return err(reply,404,'MEDIA_NOT_IN_LIBRARY','Cette œuvre n’est pas résolue dans la bibliothèque.');
});
app.get('/api/v1/health',async()=>({status:'ok',currentProtocol:1,minimumSupportedProtocol:1,buildVersion:buildVersion(),schemaVersion:BOOTSTRAP_SCHEMA_VERSION}));
app.get('/api/v1/openapi.json',async()=>runtimeOpenApi());
app.get('/api/v1/public/extension-releases/:browser',async(req:any,reply:any)=>{const parsed=z.enum(['chrome','firefox']).safeParse(req.params.browser);if(!parsed.success)return err(reply,400,'VALIDATION_FAILED');const release=await pool.query('SELECT browser,version,protocol,checksum_sha256 AS "checksumSha256",artifact_url AS "artifactUrl",update_manifest_url AS "updateManifestUrl",installation_mode AS "installationMode",published_at AS "publishedAt" FROM extension_release WHERE browser=$1',[parsed.data]);if(!release.rowCount)return err(reply,404,'EXTENSION_RELEASE_NOT_PUBLISHED','Aucune version vérifiée n’est publiée.');return release.rows[0]});
app.get('/api/v1/releases',async()=>{const r=await pool.query(`SELECT a.media_id AS "mediaId",favlib_display_title(m.id,NULL)->>'title' AS title,favlib_display_title(m.id,NULL) AS "titleSelection",m.type,a.release_key AS "releaseKey",a.status,a.announced_at AS "announcedAt" FROM release_announcement a JOIN media m ON m.id=a.media_id ORDER BY a.announced_at DESC LIMIT 30`);return {items:r.rows.map((row:any)=>({...row,coverUrl:row.title?`/api/v1/catalog/media/${encodeURIComponent(row.mediaId)}/cover`:null}))}});
app.post('/api/v1/progression/observations',async(req:any,reply:any)=>{const p=z.object({mediaId:z.string().min(1).max(300),source:z.string().min(1).max(200),position:z.string().min(1).max(100),kind:z.enum(['season','volume','chapter','episode','special']).default('episode'),confidence:z.enum(['high','medium','low']),consented:z.boolean()}).safeParse(req.body);if(!p.success)return err(reply,400,'VALIDATION_FAILED');const next=position(p.data.position,p.data.kind);const current=await pool.query('SELECT position_kind AS "kind",position_number AS "number",position_raw AS "raw" FROM favorite_progress WHERE user_id=$1 AND media_id=$2 AND position_kind=$3',[req.user.id,p.data.mediaId,p.data.kind]);const currentPosition=current.rowCount?{kind:current.rows[0].kind,number:current.rows[0].number===null?undefined:Number(current.rows[0].number),raw:current.rows[0].raw}:null;const observation={mediaId:p.data.mediaId,source:p.data.source,position:next,confidence:p.data.confidence,consented:p.data.consented,observedAt:new Date().toISOString()};if(!acceptObservation(currentPosition,observation))return err(reply,409,'PROGRESSION_REJECTED','Observation non consentie, incertaine ou régressive.');const client=await pool.connect();try{await client.query('BEGIN');const saved=await client.query('INSERT INTO progression_observation(user_id,media_id,source,position_kind,position_number,position_raw,confidence,consented,observed_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(user_id,media_id,source,position_kind,position_raw,observed_at) DO UPDATE SET confidence=excluded.confidence RETURNING id',[req.user.id,p.data.mediaId,p.data.source,next.kind,next.number??null,next.raw,p.data.confidence,p.data.consented,observation.observedAt]);await client.query('INSERT INTO favorite_progress(user_id,media_id,position_kind,position_number,position_raw,observation_id) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(user_id,media_id,position_kind) DO UPDATE SET position_number=excluded.position_number,position_raw=excluded.position_raw,observation_id=excluded.observation_id,updated_at=now()',[req.user.id,p.data.mediaId,next.kind,next.number??null,next.raw,saved.rows[0].id]);await client.query('COMMIT');return reply.code(201).send({ok:true,mediaId:p.data.mediaId,position:next.raw});}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}});
app.get('/api/v1/progression',async(req:any)=>{const r=await pool.query('SELECT media_id AS "mediaId",position_kind AS "kind",position_number AS "number",position_raw AS "raw",updated_at AS "updatedAt" FROM favorite_progress WHERE user_id=$1 ORDER BY updated_at DESC',[req.user.id]);return {items:r.rows}});
app.get('/api/v1/notifications',async(req:any)=>{const r=await pool.query(`SELECT n.id,n.kind,n.payload,n.created_at AS "createdAt",n.read_at AS "readAt",
  favlib_display_title(m.id,$1::uuid)->>'title' AS title,
  favlib_display_title(m.id,$1::uuid) AS "titleSelection"
  FROM personal_notification n
  LEFT JOIN media m ON m.id=COALESCE(n.payload#>>'{release,mediaId}',split_part(n.release_key,'|',1))
  WHERE n.user_id=$1 ORDER BY n.created_at DESC LIMIT 100`,[req.user.id]);return {items:r.rows}});
app.get('/api/v1/reviews',async(req:any)=>{const r=await pool.query(`SELECT r.id,r.favorite_title AS "favoriteTitle",r.favorite_url AS "favoriteUrl",r.provider,r.status,r.reason,r.created_at AS "createdAt",r.resolved_at AS "resolvedAt",LEAST(count(c.id)::int,5) AS "candidateCount" FROM favorite_review r LEFT JOIN favorite_review_candidate c ON c.review_id=r.id WHERE r.user_id=$1 GROUP BY r.id ORDER BY CASE WHEN r.status='PENDING' THEN 0 ELSE 1 END,r.created_at DESC`,[req.user.id]);return {items:r.rows,pendingCount:r.rows.filter((row:any)=>row.status==='PENDING').length}});
app.get('/api/v1/reviews/:id',async(req:any,reply:any)=>{const review=await pool.query(`SELECT id,installation_id AS "installationId",bookmark_id AS "bookmarkId",favorite_title AS "favoriteTitle",favorite_url AS "favoriteUrl",provider,status,reason,selected_candidate_id AS "selectedCandidateId",decision,created_at AS "createdAt",resolved_at AS "resolvedAt" FROM favorite_review WHERE id=$1 AND user_id=$2`,[req.params.id,req.user.id]);if(!review.rowCount)return err(reply,404,'REVIEW_NOT_FOUND');const candidates=await pool.query(`SELECT id,provider_id AS "providerId",canonical_title AS "canonicalTitle",hit_title AS "hitTitle",associated_titles AS "associatedTitles",type,year,start_date AS "startDate",status,authors,categories,genres,image,url,media_id AS "mediaId" FROM favorite_review_candidate WHERE review_id=$1 ORDER BY canonical_title LIMIT 5`,[req.params.id]);const favoriteTitle=review.rows[0].favoriteTitle;return {...review.rows[0],candidates:candidates.rows,google:{anilist:`https://www.google.com/search?q=${encodeURIComponent(favoriteTitle+' site:anilist.co')}`,mangaupdates:`https://www.google.com/search?q=${encodeURIComponent(favoriteTitle+' site:mangaupdates.com')}`}}});
async function refreshReviewQueue(userId:string){const pending=await pool.query("SELECT count(*)::int AS count FROM favorite_review WHERE user_id=$1 AND status='PENDING'",[userId]);const count=Number(pending.rows[0]?.count??0);if(!count){await pool.query("DELETE FROM personal_notification WHERE user_id=$1 AND kind='FAVORITE_REVIEW_REQUIRED' AND release_key='favorite-review-queue'",[userId]);return}await pool.query("INSERT INTO personal_notification(user_id,release_key,kind,payload) VALUES($1,'favorite-review-queue','FAVORITE_REVIEW_REQUIRED',jsonb_build_object('title','Correspondances à résoudre','message',$2::text,'count',$3::int,'url','/review')) ON CONFLICT(user_id,release_key,kind) DO UPDATE SET payload=excluded.payload,read_at=NULL",[userId,`Il reste ${count} favori${count>1?'s':''} à vérifier.`,count])}
async function resolveReview(reviewId:string,userId:string,candidateId:string,decision:Record<string,unknown>,reply:any){const client=await pool.connect();try{await client.query('BEGIN');const row=await client.query(`SELECT r.*,c.id AS candidate_id,c.provider_id,c.canonical_title,c.type,c.url,c.payload,c.media_id FROM favorite_review r JOIN favorite_review_candidate c ON c.review_id=r.id AND c.id=$3 WHERE r.id=$1 AND r.user_id=$2 AND r.status='PENDING' FOR UPDATE`,[reviewId,userId,candidateId]);if(!row.rowCount){await client.query('ROLLBACK');return err(reply,404,'REVIEW_CANDIDATE_NOT_FOUND')};const x=row.rows[0];let mediaId=x.media_id;if(!mediaId){mediaId=`${x.provider}:${x.provider_id}`;await client.query('INSERT INTO media(id,type) VALUES($1,$2) ON CONFLICT(id) DO NOTHING',[mediaId,x.type||'MANGA']);await client.query("INSERT INTO media_external_id(media_id,provider,external_id,provenance) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING",[mediaId,x.provider,x.provider_id,{source:'favorite-review',reviewId}]);await client.query("INSERT INTO media_title(media_id,text,normalized_text,language,kind,title_type,connector,confidence,provenance) VALUES($1,$2,lower(regexp_replace($2,'[^[:alnum:]]+',' ','g')),NULL,'official','canonical',$3,1,$4) ON CONFLICT DO NOTHING",[mediaId,x.canonical_title,x.provider,{provider:x.provider,externalId:x.provider_id}]);await client.query("INSERT INTO media_metadata(media_id,provider,external_id,source_url,status,resolved_at,updated_at) VALUES($1,$2,$3,$4,'ACTIVE',now(),now()) ON CONFLICT(media_id) DO UPDATE SET status='ACTIVE',external_id=excluded.external_id,source_url=excluded.source_url,updated_at=now()",[mediaId,x.provider,x.provider_id,x.url])}await client.query("UPDATE bookmark_media_link SET media_id=$1,status='matched',evidence=evidence||$2::jsonb WHERE user_id=$3 AND installation_id=$4 AND bookmark_id=$5",[mediaId,JSON.stringify({resolution:'user-review',provider:x.provider,providerId:x.provider_id}),userId,x.installation_id,x.bookmark_id]);await client.query("UPDATE favorite_review SET status='RESOLVED',selected_candidate_id=$2,decision=$3,resolved_at=now() WHERE id=$1 AND user_id=$4",[reviewId,candidateId,JSON.stringify(decision),userId]);await client.query('COMMIT');await refreshReviewQueue(userId);return {ok:true,reviewId,mediaId,status:'RESOLVED'}}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}}
app.post('/api/v1/reviews/:id/resolve',async(req:any,reply:any)=>{const p=z.object({candidateId:z.string().uuid()}).safeParse(req.body);if(!p.success)return err(reply,400,'VALIDATION_FAILED');return resolveReview(req.params.id,req.user.id,p.data.candidateId,{kind:'candidate'},reply)});
app.post('/api/v1/reviews/:id/no-match',async(req:any,reply:any)=>{const r=await pool.query("UPDATE favorite_review SET status='NO_MATCH',decision=$3::jsonb,resolved_at=now() WHERE id=$1 AND user_id=$2 AND status='PENDING' RETURNING id",[req.params.id,req.user.id,JSON.stringify({kind:'no-match'})]);if(!r.rowCount)return err(reply,404,'REVIEW_NOT_FOUND');await refreshReviewQueue(req.user.id);return {ok:true,status:'NO_MATCH'}});
app.post('/api/v1/reviews/:id/manual',async(req:any,reply:any)=>{const p=z.object({provider:z.enum(['anilist','mangaupdates']),id:z.string().trim().min(1).max(80).optional(),url:z.string().url().optional()}).refine(v=>Boolean(v.id||v.url)).safeParse(req.body);if(!p.success)return err(reply,400,'VALIDATION_FAILED');let id=p.data.id;if(p.data.url){try{const u=new URL(p.data.url);const valid=p.data.provider==='anilist'?u.hostname==='anilist.co'||u.hostname.endsWith('.anilist.co'):u.hostname==='mangaupdates.com'||u.hostname.endsWith('.mangaupdates.com');if(!valid)return err(reply,422,'PROVIDER_URL_MISMATCH');const match=p.data.provider==='anilist'?u.pathname.match(/\/(?:anime|manga)\/(\d+)/u):u.pathname.match(/\/series\/(\d+)/u);id=match?.[1]}catch{return err(reply,422,'PROVIDER_URL_INVALID')}}if(!id||!/^\d{1,12}$/u.test(id))return err(reply,422,'PROVIDER_ID_INVALID');const c=await pool.query('SELECT id FROM favorite_review_candidate WHERE review_id=$1 AND provider_id=$2',[req.params.id,id]);if(!c.rowCount)return err(reply,422,'PROVIDER_NOT_VERIFIED','Le fournisseur doit être vérifié avant rattachement.');return resolveReview(req.params.id,req.user.id,c.rows[0].id,{kind:'manual',provider:p.data.provider,id},reply)});
type CalendarFilters={followed?:boolean;favorites?:boolean;categories?:string[];mediaTypes?:string[]};
const calendarFilters=z.object({followed:z.boolean().optional(),favorites:z.boolean().optional(),categories:z.array(z.enum(['airing','release'])).max(2).optional(),mediaTypes:z.array(z.enum(['ANIME','MANGA','MANHWA','MANHUA'])).max(4).optional()}).default({});
function calendarLocal(iso:string,timeZone:string){return new Intl.DateTimeFormat('fr-FR',{timeZone,dateStyle:'short',timeStyle:'short'}).format(new Date(iso));}
async function calendarRows(userId:string,filters:CalendarFilters,timeZone='UTC'){
  const types=filters.mediaTypes?.length?filters.mediaTypes:null;
  const categories=filters.categories?.length?filters.categories:null;
  const followed=filters.followed??filters.favorites??true;
  const result=await pool.query(`WITH favorite_media AS (SELECT DISTINCT media_id FROM bookmark_media_link WHERE user_id=$1 AND status IN ('matched','accepted') AND media_id IS NOT NULL), events AS (
    SELECT 'airing'::text AS category,'ANIME'::text AS event_type,a.media_id,a.episode::text AS release_key,a.airing_at_utc AS starts_at,a.provider,a.schedule_status AS status
    FROM media_airing a JOIN favorite_media f ON f.media_id=a.media_id
    WHERE a.airing_at_utc IS NOT NULL
    UNION ALL
    SELECT 'release'::text,m.type,o.media_id,o.provider_release_key,o.release_date,'mangaupdates', 'ANNOUNCED'
    FROM mangaupdates_release_observation o JOIN media m ON m.id=o.media_id JOIN favorite_media f ON f.media_id=o.media_id
    WHERE o.release_date IS NOT NULL AND m.type IN ('MANGA','MANHWA','MANHUA')
  ) SELECT e.category,e.event_type AS "type",e.media_id AS "mediaId",e.release_key AS "releaseKey",e.provider,e.status,e.starts_at AS "startsAt",
    COALESCE(favlib_display_title(e.media_id,$1::uuid)->>'title',e.media_id) AS title,
    favlib_display_title(e.media_id,$1::uuid) AS "titleSelection",
    (SELECT favlib_clean_display_title(t.text) FROM media_title t WHERE t.media_id=e.media_id AND t.kind='personal' AND t.provenance->>'userId'=$1::text AND favlib_clean_display_title(t.text) IS NOT NULL ORDER BY t.id DESC LIMIT 1) AS "personalTitle",
    CASE WHEN c.media_id IS NOT NULL THEN '/api/v1/catalog/media/'||replace(e.media_id,'/','%2F')||'/cover' END AS "coverUrl"
  FROM events e LEFT JOIN media_cover c ON c.media_id=e.media_id AND c.status='ACTIVE'
  WHERE ($2::boolean OR e.media_id IN (SELECT media_id FROM favorite_media))
    AND ($3::text[] IS NULL OR e.category=ANY($3)) AND ($4::text[] IS NULL OR e.event_type=ANY($4))
  ORDER BY e.starts_at ASC,e.media_id,e.release_key LIMIT 500`,[userId,followed,categories,types]);
  return result.rows.map((row:any)=>({...row,localStart:calendarLocal(new Date(row.startsAt).toISOString(),timeZone),startsAtUtc:new Date(row.startsAt).toISOString()}));
}
function icsEscape(value:string){return value.replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n')}
function icsDate(value:string){return new Date(value).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}
function calendarIcs(rows:any[],timeZone:string){const now=icsDate(new Date().toISOString());const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FavLib//Calendar//FR','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-TIMEZONE:'+icsEscape(timeZone)];for(const row of rows){const uid=`${row.category}-${row.mediaId}-${row.releaseKey}@favlib`;const end=new Date(new Date(row.startsAt).getTime()+60*60*1000).toISOString();lines.push('BEGIN:VEVENT',`UID:${icsEscape(uid)}`,`DTSTAMP:${now}`,`DTSTART:${icsDate(row.startsAt)}`,`DTEND:${icsDate(end)}`,`SUMMARY:${icsEscape(`${row.category==='airing'?'Épisode':'Release'} · ${row.personalTitle??row.title} · ${row.releaseKey}`)}`,`DESCRIPTION:${icsEscape(`${row.title}${row.personalTitle?` · Favori : ${row.personalTitle}`:''} · ${row.provider}`)}`,`CATEGORIES:${row.category==='airing'?'ANIME AIRING':'MANGA RELEASE'}`,'END:VEVENT')}lines.push('END:VCALENDAR');return lines.join('\r\n')+'\r\n'}
app.get('/api/v1/calendar',async(req:any,reply:any)=>{const parsed=calendarFilters.safeParse({followed:req.query?.followed===undefined?undefined:req.query.followed!=='false',favorites:req.query?.favorites===undefined?undefined:req.query.favorites!=='false',categories:typeof req.query?.category==='string'?req.query.category.split(','):undefined,mediaTypes:typeof req.query?.type==='string'?req.query.type.split(','):undefined});if(!parsed.success)return err(reply,400,'VALIDATION_FAILED','Filtres calendrier invalides.');const pref=await pool.query('SELECT timezone FROM user_catalog_preference WHERE user_id=$1',[req.user.id]);const timeZone=pref.rows[0]?.timezone??'UTC';return {items:await calendarRows(req.user.id,parsed.data,timeZone),timeZone,filters:parsed.data}});
