app.get('/api/v1/calendar/feeds/:id',async(req:any,reply:any)=>{const token=typeof req.query?.token==='string'?req.query.token:'';const row=await pool.query('SELECT * FROM calendar_feed WHERE id=$1 AND token_hash=$2 AND revoked_at IS NULL',[req.params.id,digest(token)]);if(!row.rowCount)return err(reply,404,'CALENDAR_FEED_NOT_FOUND','Flux inexistant, révoqué ou jeton invalide.');const pref=await pool.query('SELECT timezone FROM user_catalog_preference WHERE user_id=$1',[row.rows[0].user_id]);const timeZone=pref.rows[0]?.timezone??'UTC';const rows=await calendarRows(row.rows[0].user_id,row.rows[0].filters??{},timeZone);await pool.query('UPDATE calendar_feed SET last_used_at=now() WHERE id=$1',[req.params.id]);return reply.header('Content-Type','text/calendar; charset=utf-8').header('Cache-Control','private, no-store').send(calendarIcs(rows,timeZone))});
