app.get('/api/v1/extension/report',async(req:any)=>{const rows=await pool.query(`SELECT i.bookmark_id AS "bookmarkId",i.classification_status AS status,i.payload->>'url' AS url,m.type,l.media_id AS "mediaId" FROM bookmark_import_item i LEFT JOIN bookmark_media_link l ON l.user_id=i.user_id AND l.installation_id=i.installation_id AND l.bookmark_id=i.bookmark_id AND l.status IN ('matched','accepted') LEFT JOIN media m ON m.id=l.media_id WHERE i.user_id=$1 AND i.installation_id=$2 AND i.event<>'removed'`,[req.user.id,req.device.installation_id]);const byDomain:Record<string,number>={},byType:Record<string,{favorites:number;works:Set<string>}>= {};for(const row of rows.rows){let domain='invalid';try{domain=new URL(row.url).hostname.toLowerCase().replace(/^www\./,'')}catch{}byDomain[domain]=(byDomain[domain]??0)+1;const type=row.type??'UNRESOLVED';const group=byType[type]??={favorites:0,works:new Set<string>()};group.favorites++;if(row.mediaId)group.works.add(row.mediaId);byType[type]=group;}return {inventoryTotal:rows.rowCount,byDomain:Object.entries(byDomain).sort((a,b)=>b[1]-a[1]).map(([domain,favorites])=>({domain,favorites})),byType:Object.entries(byType).map(([type,value])=>({type,favorites:value.favorites,works:value.works.size}))}});
