app.get('/api/v1/extension/progression',async(req:any,reply:any)=>{const bookmarkId=typeof req.query?.bookmarkId==='string'?req.query.bookmarkId.slice(0,200):'';if(!bookmarkId)return err(reply,400,'VALIDATION_FAILED');const link=await pool.query("SELECT media_id AS \"mediaId\" FROM bookmark_media_link WHERE user_id=$1 AND installation_id=$2 AND bookmark_id=$3 AND status IN ('matched','accepted') LIMIT 1",[req.user.id,req.device.installation_id,bookmarkId]);if(!link.rowCount)return {linked:false,progress:null,availableCount:0,delta:null};const mediaId=link.rows[0].mediaId;const progress=await pool.query('SELECT position_kind AS "kind",position_number AS "number",position_raw AS "raw",updated_at AS "updatedAt" FROM favorite_progress WHERE user_id=$1 AND media_id=$2 ORDER BY updated_at DESC LIMIT 1',[req.user.id,mediaId]);const available=await pool.query("SELECT release_key AS \"releaseKey\" FROM release_origin WHERE media_id=$1 AND status='AVAILABLE' AND (user_id=$2 OR user_id IS NULL)",[mediaId,req.user.id]);const current=progress.rows[0]?.number===null||progress.rows[0]?.number===undefined?null:Number(progress.rows[0].number);const numbers=available.rows.map(row=>Number(String(row.releaseKey).split('|')[3])).filter(Number.isFinite);const next=numbers.length?Math.max(...numbers):null;return {linked:true,mediaId,progress:progress.rows[0]??null,availableCount:available.rowCount,delta:current!==null&&next!==null?next-current:null}});
app.post('/api/v1/extension/page-metadata',async(req:any,reply:any)=>{
  const parsed=extensionPageMetadataContract.safeParse(req.body);if(!parsed.success)return err(reply,400,'VALIDATION_FAILED');
  if(!sameSiteUrl(parsed.data.pageUrl,parsed.data.canonicalUrl)||suspiciousPageMetadata(parsed.data))return reply.code(202).send({accepted:false,reason:'PAGE_METADATA_DIVERTED'});
  const wanted=sourceIdentityFromUrl(parsed.data.pageUrl)??sourceIdentityFromUrl(parsed.data.canonicalUrl);
  const links=await pool.query(`SELECT l.media_id AS "mediaId",i.payload->>'url' AS url FROM bookmark_media_link l JOIN bookmark_import_item i ON i.user_id=l.user_id AND i.installation_id=l.installation_id AND i.bookmark_id=l.bookmark_id WHERE l.user_id=$1 AND l.installation_id=$2 AND l.status IN ('matched','accepted') AND i.event<>'removed'`,[req.user.id,req.device.installation_id]);
  const link=links.rows.find(row=>row.url===parsed.data.pageUrl||(wanted&&sourceIdentityFromUrl(row.url)?.key===wanted.key));if(!link)return reply.code(202).send({accepted:false,reason:'PAGE_NOT_FAVORITED'});
  const inputFingerprint=digest(JSON.stringify(parsed.data)),pageKey=digest(parsed.data.canonicalUrl);
  let changed=false;const client=await pool.connect();try{await client.query('BEGIN');const receipt=await client.query('INSERT INTO extension_metadata_receipt(device_id,media_id,page_key,input_fingerprint) VALUES($1,$2,$3,$4) ON CONFLICT(device_id,media_id,page_key) DO UPDATE SET input_fingerprint=excluded.input_fingerprint,received_at=now() WHERE extension_metadata_receipt.input_fingerprint<>excluded.input_fingerprint RETURNING input_fingerprint',[req.device.id,link.mediaId,pageKey,inputFingerprint]);changed=Boolean(receipt.rowCount);if(changed&&parsed.data.title)await client.query("INSERT INTO media_title(media_id,text,normalized_text,language,kind,connector,provenance) VALUES($1,$2,$3,NULL,'page','source-page',$4) ON CONFLICT DO NOTHING",[link.mediaId,parsed.data.title,normalizeText(parsed.data.title),{sourceUrl:parsed.data.canonicalUrl,confidence:parsed.data.confidence}]);if(changed)for(const [field,value] of Object.entries({title:parsed.data.title,image:parsed.data.image,canonicalUrl:parsed.data.canonicalUrl,type:parsed.data.type,year:parsed.data.year,format:parsed.data.format})){if(value!==undefined)await client.query('INSERT INTO metadata_assertion(media_id,field,value,provider,source_url,confidence,attribution) VALUES($1,$2,$3,\'source-page\',$4,$5,NULL) ON CONFLICT(media_id,field,provider,source_url) DO UPDATE SET value=excluded.value,confidence=excluded.confidence,asserted_at=now()',[link.mediaId,field,JSON.stringify(value),parsed.data.canonicalUrl,parsed.data.confidence]);}if(changed&&parsed.data.image&&parsed.data.title)await enqueueMetadata(client,req.user.id,link.mediaId,parsed.data.title,parsed.data.pageUrl);await client.query('COMMIT');}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}
  return reply.code(202).send({accepted:true,unchanged:!changed});
});
app.get('/api/v1/extension/page-resolution',async(req:any,reply:any)=>{
  const parsed=z.string().url().max(4096).safeParse(req.query?.url);if(!parsed.success||!/^https?:/i.test(parsed.data))return err(reply,400,'VALIDATION_FAILED');
  const wanted=sourceIdentityFromUrl(parsed.data);
  const candidates=await pool.query(`SELECT i.bookmark_id AS "bookmarkId",i.payload->>'url' AS url,l.media_id AS "mediaId",l.status FROM bookmark_import_item i LEFT JOIN bookmark_media_link l ON l.user_id=i.user_id AND l.installation_id=i.installation_id AND l.bookmark_id=i.bookmark_id AND l.classifier_version='source-v1' WHERE i.user_id=$1 AND i.installation_id=$2 AND i.event<>'removed'`,[req.user.id,req.device.installation_id]);
  const match=candidates.rows.find(row=>row.url===parsed.data||(wanted&&sourceIdentityFromUrl(row.url)?.key===wanted.key));
  if(!match)return {state:'untracked'};
  if(!match.mediaId||!['matched','accepted'].includes(match.status))return {state:'associating'};
  const details=await pool.query(`SELECT m.id,m.type,m.format,favlib_display_title(m.id,$2::uuid)->>'title' AS title,favlib_display_title(m.id,$2::uuid) AS "titleSelection" FROM media m WHERE m.id=$1`,[match.mediaId,req.user.id]);
  const progress=await pool.query('SELECT position_kind AS "kind",position_raw AS "raw",updated_at AS "updatedAt" FROM favorite_progress WHERE user_id=$1 AND media_id=$2 ORDER BY updated_at DESC LIMIT 1',[req.user.id,match.mediaId]);
  return {state:'known',media:details.rows[0]??{id:match.mediaId,title:null,format:null,type:'UNKNOWN'},sourceIdentity:wanted,progress:progress.rows[0]??null,coverUrl:`/api/v1/extension/favorites/${encodeURIComponent(match.mediaId)}/cover`};
});
app.get('/api/v1/extension/favorites',async(req:any,reply:any)=>{
  const parsed=z.coerce.number().int().min(1).max(30).default(12).safeParse(req.query?.limit);if(!parsed.success)return err(reply,400,'VALIDATION_FAILED');
  const result=await pool.query(`WITH favorites AS (
    SELECT DISTINCT l.media_id FROM bookmark_media_link l
    JOIN bookmark_import_item i ON i.user_id=l.user_id AND i.installation_id=l.installation_id AND i.bookmark_id=l.bookmark_id
    WHERE l.user_id=$1 AND l.status IN ('matched','accepted') AND i.event<>'removed'
  ) SELECT m.id,COALESCE(favlib_display_title(m.id,$1::uuid)->>'title',m.id) AS title,
    favlib_display_title(m.id,$1::uuid) AS "titleSelection",
    m.type,m.format,
    (SELECT jsonb_build_object('kind',p.position_kind,'raw',p.position_raw,'updatedAt',p.updated_at) FROM favorite_progress p WHERE p.user_id=$1 AND p.media_id=m.id ORDER BY p.updated_at DESC LIMIT 1) AS progress,
    (SELECT jsonb_build_object('key',a.release_key,'at',a.announced_at) FROM release_announcement a WHERE a.media_id=m.id ORDER BY a.announced_at DESC LIMIT 1) AS "latestRelease",
    CASE WHEN EXISTS(SELECT 1 FROM media_cover c WHERE c.media_id=m.id AND c.status='ACTIVE') THEN '/api/v1/extension/favorites/'||replace(m.id,'/','%2F')||'/cover' END AS "coverUrl"
  FROM favorites f JOIN media m ON m.id=f.media_id
  ORDER BY COALESCE((SELECT max(p.updated_at) FROM favorite_progress p WHERE p.user_id=$1 AND p.media_id=m.id),m.created_at) DESC,m.id LIMIT $2`,[req.user.id,parsed.data]);
  return {items:result.rows};
});
app.get('/api/v1/extension/favorites/:mediaId/cover',async(req:any,reply:any)=>{
  const cover=await pool.query(`SELECT c.mime_type,COALESCE(a.data,c.data) AS data,c.provider,c.attribution FROM media_cover c
    LEFT JOIN catalog_image_asset a ON a.sha256=c.asset_sha256
    WHERE c.media_id=$1 AND c.status='ACTIVE' AND EXISTS(SELECT 1 FROM bookmark_media_link l JOIN bookmark_import_item i ON i.user_id=l.user_id AND i.installation_id=l.installation_id AND i.bookmark_id=l.bookmark_id WHERE l.media_id=c.media_id AND l.user_id=$2 AND l.status IN ('matched','accepted') AND i.event<>'removed')`,[req.params.mediaId,req.user.id]);
  if(!cover.rowCount||!cover.rows[0].data)return err(reply,404,'COVER_NOT_AVAILABLE','Aucune couverture favorite locale n’est disponible.');
  const data=Buffer.from(cover.rows[0].data,'base64'),etag=`"${createHash('sha256').update(data).digest('base64url')}"`;if(req.headers['if-none-match']===etag)return reply.code(304).send();
  return reply.type(cover.rows[0].mime_type).header('Cache-Control','private, max-age=2592000, immutable').header('ETag',etag).header('Content-Length',String(data.length)).header('X-FavLib-Cover-Provider',cover.rows[0].provider).send(data);
});
app.post('/api/v1/extension/devices/:id/rotate',async(req:any,reply:any)=>{const token=newOpaqueSecret(32);const r=await pool.query('UPDATE extension_device SET token_hash=$1,revoked_at=NULL WHERE id=$2 AND user_id=$3 RETURNING id',[digest(token),req.params.id,req.user.id]);if(!r.rowCount)return err(reply,404,'DEVICE_NOT_FOUND');await pool.query('INSERT INTO security_event(actor_user_id,event,target_id,result) VALUES($1,\'device_token_rotated\',$2,\'success\')',[req.user.id,req.params.id]);return {ok:true,deviceId:r.rows[0].id,deviceToken:token}});
app.post('/api/v1/account/deletion-requests',async(req:any,reply:any)=>{const token=newOpaqueSecret(32);const r=await pool.query('INSERT INTO account_deletion_request(user_id,token_hash) VALUES($1,$2) RETURNING id,expires_at AS "expiresAt"',[req.user.id,digest(token)]);return reply.code(201).send({requestId:r.rows[0].id,token,expiresAt:r.rows[0].expiresAt})});
app.delete('/api/v1/account/deletion',async(req:any,reply:any)=>{const parsed=z.object({token:z.string().min(32).max(100).regex(/^[A-Za-z0-9_-]+$/)}).safeParse(req.body);if(!parsed.success)return err(reply,400,'INVALID_DELETION_TOKEN');const client=await pool.connect();try{await client.query('BEGIN');const request=await client.query('SELECT id,user_id,completed_at FROM account_deletion_request WHERE token_hash=$1 AND user_id=$2 AND expires_at>now() FOR UPDATE',[digest(parsed.data.token),req.user.id]);if(!request.rowCount){await client.query('ROLLBACK');return err(reply,404,'DELETION_REQUEST_NOT_FOUND');}if(request.rows[0].completed_at){await client.query('COMMIT');return {ok:true,deleted:true,idempotent:true};}await client.query("INSERT INTO deletion_tombstone(entity_type,entity_id,reason) SELECT 'user',$1,'account_delete' WHERE NOT EXISTS(SELECT 1 FROM deletion_tombstone WHERE entity_type='user' AND entity_id=$1)",[req.user.id]);await client.query('UPDATE account_deletion_request SET completed_at=now() WHERE id=$1',[request.rows[0].id]);await client.query('DELETE FROM app_user WHERE id=$1',[req.user.id]);await client.query('COMMIT');return {ok:true,deleted:true};}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}});
app.get('/api/v1/extension/diagnostic/covers-missing',async(req:any)=>{const result=await pool.query(`SELECT m.id AS "mediaId",m.type,COALESCE(favlib_display_title(m.id,$1::uuid)->>'title','(sans titre)') AS title FROM media m JOIN bookmark_media_link l ON l.media_id=m.id AND l.user_id=$1 AND l.installation_id=$2 AND l.status IN ('matched','accepted','review') LEFT JOIN media_cover c ON c.media_id=m.id AND c.status='ACTIVE' WHERE c.media_id IS NULL ORDER BY title,m.id`,[req.user.id,req.device.installation_id]);return {count:result.rowCount,items:result.rows};});
app.setErrorHandler((e,req,reply)=>{if((e as any).statusCode===413)return err(reply,413,'PAYLOAD_TOO_LARGE','Corps trop volumineux.');req.log.error(e);return err(reply,500,'INTERNAL_ERROR','Erreur interne.');});
if(runtime.nodeEnv!=='test'){await app.listen({host:'0.0.0.0',port:runtime.port});let stopping=false;const shutdown=async(signal:string)=>{if(stopping)return;stopping=true;app.log.info({signal},'graceful shutdown');await app.close();await pool.end()};process.once('SIGTERM',()=>void shutdown('SIGTERM'));process.once('SIGINT',()=>void shutdown('SIGINT'))} export {app,pool,runtimeOpenApi,runtimeRouteOperations};
